20	/**
21	 * Maps Owner & OwnerDto using Mapstruct
22	 */
23	@Mapper(uses = PetMapper.class)
24	public interface OwnerMapper {
25	
26	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
27	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
28	    @Mapping(target = "initials", expression = "java(initials(owner))")
29	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
30	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
31	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
32	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
33	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
34	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
35	    @Mapping(target = "locality", expression = "java(locality(owner))")
36	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
37	    @Mapping(target = "bulkSignupWarning", expression = "java(bulkSignupWarning(owner))")
38	    @Mapping(target = "possibleDuplicate", expression = "java(possibleDuplicate(owner))")
39	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
40	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
41	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
42	    OwnerDto toOwnerDto(Owner owner);
43	
44	    Owner toOwner(OwnerDto ownerDto);
45	
46	    /**
47	     * Formats an owner's stored names as {@code 'LastName, FirstName'}.
48	     */
49	    default String displayName(Owner owner) {
50	        if (owner == null) {
51	            return null;
52	        }
53	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
54	        String firstName = owner.getFirstName() == null ? "" : owner.getFirstName();
55	        return lastName + ", " + firstName;
56	    }
57	
58	    /**
59	     * Composes the owner's salutation as {@code '<title> <lastName>'} — the title, a single
60	     * space and the last name — or just the last name when no (blank/absent) title is given.
61	     */
62	    default String salutation(Owner owner) {
63	        if (owner == null) {
64	            return null;
65	        }
66	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
67	        String title = owner.getTitle();
68	        if (title == null || title.isBlank()) {
69	            return lastName;
70	        }
71	        return title + " " + lastName;
72	    }
73	
74	    /**
75	     * Returns the upper-cased first letters of firstName and lastName,
76	     * dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
77	     */
78	    default String initials(Owner owner) {
79	        if (owner == null) {
80	            return null;
81	        }
82	        StringBuilder sb = new StringBuilder();
83	        String firstName = owner.getFirstName();
84	        String lastName = owner.getLastName();
85	        if (firstName != null && !firstName.isEmpty()) {
86	            sb.append(Character.toUpperCase(firstName.charAt(0))).append('.');
87	        }
88	        if (lastName != null && !lastName.isEmpty()) {
89	            sb.append(Character.toUpperCase(lastName.charAt(0))).append('.');
90	        }
91	        return sb.toString();
92	    }
93	
94	    /**
95	     * Formats the owner's stored E.164 {@code telephone} for human display: the country code,
96	     * a space, and the national digits grouped in threes separated by spaces, e.g.
97	     * {@code '+61412345678'} becomes {@code '+61 412 345 678'}. The raw {@code telephone} is
98	     * left unchanged in E.164 form.
99	     */
100	    default String telephoneDisplay(Owner owner) {
101	        if (owner == null) {
102	            return null;
103	        }
104	        return TelephoneNormalizer.toDisplay(owner.getTelephone());
105	    }
106	
107	    /**
108	     * Formats the owner's membership number as {@code '<customerCode>-M<YY>'}: the customer
109	     * code, the literal {@code '-M'}, and the last two digits of the fiscal year derived from
110	     * the (business-day-adjusted) registrationDate. Returns {@code null} unless both the
111	     * customer code and registration date are present.
112	     */
113	    default String membershipNumber(Owner owner) {
114	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
115	            return null;
116	        }
117	        int fiscalYear = RegistrationDateNormalizer.fiscalYear(owner.getRegistrationDate());
118	        String yy = String.format("%02d", fiscalYear % 100);
119	        return owner.getCustomerCode() + "-M" + yy;
120	    }
121	
122	    /**
123	     * Derives the owner's {@code fiscalYear}, formatted {@code 'FY<YY>'}: the literal {@code 'FY'}
124	     * and the last two digits of the fiscal year derived from the (business-day-adjusted)
125	     * registrationDate. The fiscal year starts on 1 July. Returns {@code null} when no registration
126	     * date is present.
127	     */
128	    default String fiscalYear(Owner owner) {
129	        if (owner == null || owner.getRegistrationDate() == null) {
130	            return null;
131	        }
132	        int fiscalYear = RegistrationDateNormalizer.fiscalYear(owner.getRegistrationDate());
133	        return String.format("FY%02d", fiscalYear % 100);
134	    }
135	
136	    /**
137	     * Computes the owner's {@code checkDigit}: a single Luhn check digit (0-9) over the digits
138	     * contained in the {@code customerCode}. Returns {@code null} when no customer code is present.
139	     */
140	    default Integer checkDigit(Owner owner) {
141	        if (owner == null || owner.getCustomerCode() == null) {
142	            return null;
143	        }
144	        String code = owner.getCustomerCode();
145	        int sum = 0;
146	        boolean dbl = true;
147	        for (int i = code.length() - 1; i >= 0; i--) {
148	            char c = code.charAt(i);
149	            if (c < '0' || c > '9') {
150	                continue;
151	            }
152	            int d = c - '0';
153	            if (dbl) {
154	                d *= 2;
155	                if (d > 9) {
156	                    d -= 9;
157	                }
158	            }
159	            sum += d;
160	            dbl = !dbl;
161	        }
162	        return (10 - (sum % 10)) % 10;
163	    }
164	
165	    /**
166	     * Computes the owner's membership points. Starts at {@code 0}; adds {@code 2} when an email
167	     * address is present; adds {@code 1} when the owner has no namesakes (namesakeCount is 0);
168	     * adds {@code 2} when the owner belongs to a household of {@code 3} or more members; adds
169	     * {@code 3} when the owner's tenure exceeds one fiscal year, where tenure is the number of
170	     * elapsed fiscal years (the current fiscal year minus the registration fiscal year).
171	     */
172	    default Integer membershipPoints(Owner owner) {
173	        if (owner == null) {
174	            return null;
175	        }
176	        int points = 0;
177	        String email = owner.getEmail();
178	        if (email != null && !email.isEmpty()) {
179	            points += 2;
180	        }
181	        Integer namesakeCount = owner.getNamesakeCount();
182	        if (namesakeCount != null && namesakeCount == 0) {
183	            points += 1;
184	        }
185	        Integer householdMemberCount = owner.getHouseholdMemberCount();
186	        if (householdMemberCount != null && householdMemberCount >= 3) {
187	            points += 2;
188	        }
189	        LocalDate registrationDate = owner.getRegistrationDate();
190	        if (registrationDate != null) {
191	            int tenure = RegistrationDateNormalizer.fiscalYear(LocalDate.now())
192	                - RegistrationDateNormalizer.fiscalYear(registrationDate);
193	            if (tenure > 1) {
194	                points += 3;
195	            }
196	        }
197	        return points;
198	    }
199	
200	    /**
201	     * Derives the owner's numeric membership level from {@link #membershipPoints(Owner)}: level
202	     * {@code 1} for {@code 0-1} points, level {@code 2} for {@code 2-3} points, level {@code 3}
203	     * for {@code 4-5} points, and level {@code 4} for {@code 6} or more points.
204	     */
205	    default Integer membershipLevel(Owner owner) {
206	        if (owner == null) {
207	            return null;
208	        }
209	        int points = membershipPoints(owner);
210	        if (points <= 1) {
211	            return 1;
212	        }
213	        if (points <= 3) {
214	            return 2;
215	        }
216	        if (points <= 5) {
217	            return 3;
218	        }
219	        return 4;
220	    }
221	
222	    /**
223	     * Derives the owner's locality (region) from the {@code customerCode}, whose form is
224	     * {@code '<REGION>-<HASH8>'}: the locality is the {@code REGION} segment before the first
225	     * hyphen. Returns {@code "UNKNOWN"} when the owner has no customer code yet.
226	     */
227	    default String locality(Owner owner) {
228	        if (owner == null) {
229	            return null;
230	        }
231	        String code = owner.getCustomerCode();
232	        if (code == null) {
233	            return "UNKNOWN";
234	        }
235	        int dash = code.indexOf('-');
236	        return dash >= 0 ? code.substring(0, dash) : code;
237	    }
238	
239	    /**
240	     * Derives the owner's IANA {@code timezone} from its locality/region using the fixed
241	     * region-to-timezone table ({@code NSW -> Australia/Sydney}, {@code VIC -> Australia/Melbourne},
242	     * {@code QLD -> Australia/Brisbane}). Returns {@code null} when the region is not in the table.
243	     */
244	    default String timezone(Owner owner) {
245	        if (owner == null) {
246	            return null;
247	        }
248	        String region = locality(owner);
249	        return switch (region) {
250	            case "NSW" -> "Australia/Sydney";
251	            case "VIC" -> "Australia/Melbourne";
252	            case "QLD" -> "Australia/Brisbane";
253	            default -> null;
254	        };
255	    }
256	
257	    /**
258	     * Whether the owner carries the bulk-signup warning (more than 80 owners already created
259	     * on its registration day at creation time). A {@code null} stored value is treated as
260	     * {@code false}, so the field is always present in the response.
261	     */
262	    default Boolean bulkSignupWarning(Owner owner) {
263	        if (owner == null) {
264	            return null;
265	        }
266	        return Boolean.TRUE.equals(owner.getBulkSignupWarning());
267	    }
268	
269	    /**
270	     * Whether the owner was flagged as a possible (soft) duplicate at creation time — not a hard
271	     * duplicate, but sharing an existing owner's last name and postcode with a different telephone.
272	     * A {@code null} stored value is treated as {@code false}, so the field is always present in the
273	     * response.
274	     */
275	    default Boolean possibleDuplicate(Owner owner) {
276	        if (owner == null) {
277	            return null;
278	        }
279	        return Boolean.TRUE.equals(owner.getPossibleDuplicate());
280	    }
281	
282	    /**
283	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email address is
284	     * present, otherwise {@code PHONE}.
285	     */
286	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
287	        if (owner == null) {
288	            return null;
289	        }
290	        String email = owner.getEmail();
291	        return (email != null && !email.isEmpty())
292	            ? OwnerDto.ContactPreferenceEnum.EMAIL
293	            : OwnerDto.ContactPreferenceEnum.PHONE;
294	    }
295	
296	    /**
297	     * Derives the owner's {@code identityKey}, the single value into which duplicate detection is
298	     * consolidated: {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}.
299	     */
300	    default String identityKey(Owner owner) {
301	        return IdentityKeyNormalizer.derive(owner);
302	    }
303	
304	    /**
305	     * Derives the owner's {@code ageBand} from {@code birthDate}, measured as of the owner's
306	     * {@code registrationDate}: {@code MINOR} when under 18, {@code ADULT} when 18 to 64, and
307	     * {@code SENIOR} when 65 or older. Returns {@code null} when no birth date is known (or when
308	     * no reference registration date is available), so the field is absent from the response.
309	     */
310	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
311	        if (owner == null || owner.getBirthDate() == null) {
312	            return null;
313	        }
314	        LocalDate reference = owner.getRegistrationDate();
315	        if (reference == null) {
316	            reference = LocalDate.now();
317	        }
318	        int age = Period.between(owner.getBirthDate(), reference).getYears();
319	        if (age < 18) {
320	            return OwnerDto.AgeBandEnum.MINOR;
321	        }
322	        if (age < 65) {
323	            return OwnerDto.AgeBandEnum.ADULT;
324	        }
325	        return OwnerDto.AgeBandEnum.SENIOR;
326	    }
327	
328	    @Mapping(target = "id", ignore = true)
329	    @Mapping(target = "pets", ignore = true)
330	    Owner toOwner(OwnerFieldsDto ownerDto);
331	
332	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
333	
334	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
335	
336	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
337	        OwnerPageDto ownerPageDto = new OwnerPageDto();
338	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
339	        ownerPageDto.setPage(ownerPage.getNumber());
340	        ownerPageDto.setSize(ownerPage.getSize());
341	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
342	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
343	        return ownerPageDto;
344	    }
345	}
